        let data;
        if (!options) data = path === '/api/projects/1' ? { ...project } : tasks.map((task) => ({ ...task }));
        else {
          writes++;
          const changes = JSON.parse(options.body);
          if (path === '/api/projects/1') {
            Object.assign(project, changes);
            data = { ...project };
