            data = { id: 7, ...changes, priority: project.defaultTaskPriority, completed: false, dueDate: '' };
            tasks.push({ ...data });
          } else {
            const task = tasks.find((task) => path.endsWith(`/${task.id}`));
            Object.assign(task, changes);
            data = { ...task };
          }
        }
        return { ok: true, json: async () => data };
      },
